#include "GameCardDelegate.hpp"
#include <QPainter>
#include <QTextLayout>
namespace { constexpr int ArtworkRole=Qt::UserRole+3; QString initials(const QString& title) { QString r; for(const auto& word:title.split(' ', Qt::SkipEmptyParts)){r+=word.left(1).toUpper();if(r.size()==2)break;}return r.isEmpty()?QStringLiteral("?"):r;} }
namespace Pocket::App {
GameCardDelegate::GameCardDelegate(QObject *parent):QStyledItemDelegate(parent){} QSize GameCardDelegate::sizeHint(const QStyleOptionViewItem&,const QModelIndex&)const{return {176,232};}
void GameCardDelegate::paint(QPainter*p,const QStyleOptionViewItem&o,const QModelIndex&i)const{p->save();p->setRenderHint(QPainter::Antialiasing);p->setRenderHint(QPainter::SmoothPixmapTransform);const QRect card=o.rect.adjusted(1,1,-1,-1);const QPalette& pal=o.palette;p->setBrush(pal.base());p->setPen(QPen(o.state&QStyle::State_Selected?pal.highlight().color():pal.mid().color(),o.state&QStyle::State_Selected?2:1));p->drawRoundedRect(card,8,8);const QRect cover(card.left()+12,card.top()+10,152,152);const QString title=i.data().toString(),path=i.data(ArtworkRole).toString();QPixmap pix(path);if(!path.isEmpty()&&!pix.isNull()){const QSize s=pix.size().scaled(cover.size(),Qt::KeepAspectRatio);p->drawPixmap(QRect(cover.center()-QPoint(s.width()/2,s.height()/2),s),pix);}else{p->setPen(Qt::NoPen);p->setBrush(pal.midlight());p->drawRoundedRect(cover,6,6);QFont f=o.font;f.setPointSize(f.pointSize()+10);f.setBold(true);p->setFont(f);p->setPen(pal.text().color());p->drawText(cover,Qt::AlignCenter,initials(title));}QFont tf=o.font;tf.setBold(true);p->setFont(tf);p->setPen(pal.text().color());const QRect tr(card.left()+10,cover.bottom()+7,card.width()-20,34);QTextOption to(Qt::AlignHCenter);to.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);QTextLayout l(title,tf);l.setTextOption(to);l.beginLayout();int y=tr.top();for(int n=0;n<2;++n){QTextLine line=l.createLine();if(!line.isValid())break;line.setLineWidth(tr.width());line.setPosition({qreal(tr.left()),qreal(y)});y+=int(line.height());}l.endLayout();l.draw(p,QPoint());QFont sf=o.font;sf.setPointSize(qMax(1,sf.pointSize()-1));p->setFont(sf);p->setPen(pal.mid().color());p->drawText(QRect(card.left()+10,card.bottom()-25,card.width()-20,18),Qt::AlignHCenter|Qt::AlignVCenter,i.data(Qt::UserRole+2).toString());p->restore();}
}
